 "content": "from collections import Counter


def transform(grid):
    """Decode the coarse color matrix represented at intersections of rails."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    field = counts.most_common(1)[0][0]
    rail = next(c for c, _ in counts.most_common() if c != field)
    row_rails = [r for r in range(h) if sum(v == rail for v in grid[r]) >= w - 3]
    col_rails = [c for c in range(w) if sum(grid[r][c] == rail for r in range(h)) >= h - 3]
    # Every lattice cell is encoded by its four rail intersections. A uniform
    # four-corner color survives; otherwise the output is the field color.
    return [
        [
            (grid[r1][c1] if len({grid[r1][c1], grid[r1][c2], grid[r2][c1], grid[r2][c2]}) == 1 else field)
            for c1, c2 in zip(col_rails, col_rails[1:])
        ]
        for r1, r2 in zip(row_rails, row_rails[1:])
    ]


if __name__ == "__main__":
    pass
